# Writes the hedra command files of crane-claw's world and draws its one texture: the cabinet (back
# wall with candy-stripe wallpaper, side walls, floor, the front frame round the glass, rails, the
# prize chute, unlit bulbs), the ball pit, the two sets of lit chase-light bulbs, the gantry (bridge,
# trolley), five toys (duck, bear, bunny, ball, gem) and confetti.
# Run from models/env: /usr/bin/python3 make_env.py. hedra: up Z, front -Y (the camera side).
# World (glTF) X, Y, Z = hedra X, Z, -Y. Colours are exact Peachy Pop 16 hex (sRGB 0..1).
import math, random
from PIL import Image

def rgb(h):
    h = h.lstrip("#")
    return " ".join(f"{int(h[i:i + 2], 16) / 255:.4f}" for i in (0, 2, 4))

def mat(name, hexc, emit=False):
    s = f"material new {name} --base-color {rgb(hexc)} --no-slot"
    return s + (f" --emission {rgb(hexc)}" if emit else "")

def H(X, Y, Z):
    """world (glTF, Y up) to hedra (Z up, -Y towards the camera)"""
    return f"{X:.3f} {-Z:.3f} {Y:.3f}"

def box(name, x0, x1, y0, y1, z0, z1, m):
    """an axis-aligned box in world coordinates"""
    return [f"add mesh cube --name {name} --size 1 --location {H((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2)}",
            f"scale {x1 - x0:.3f} {z1 - z0:.3f} {y1 - y0:.3f}", "apply --scale", f"material assign {m}"]

def write(name, lines, header):
    open(f"{name}.txt", "w").write("\n".join([f"# {header} Generated by make_env.py.", "new"] + lines) + "\n")

PINK, HOT, MAG, PLUM, DARK = "#ff8686", "#fb4771", "#ce186a", "#8f0b5f", "#53034b"
WHITE, YEL, PEACH, RED = "#fdffff", "#ffec6d", "#ffa763", "#ff4040"
LILAC, PERI, BLUE, TEAL, MINT = "#ad6dea", "#9fb9ff", "#567feb", "#0a547b", "#0ce7a7"

# ---- the wallpaper: diagonal candy stripes (magenta on hot pink) with pale pink four-point stars (all
# three on the cabinet ramp: the baker snaps any other colour into it),
# 48 x 40 texels over the 4.4 x 3.6 m back wall (0.09 m a texel, two splats at 0.045)
W, Ht = 48, 40
im = Image.new("RGB", (W, Ht))
c = {k: tuple(int(v.lstrip("#")[i:i + 2], 16) for i in (0, 2, 4)) for k, v in
     {"a": HOT, "b": MAG, "s": PINK}.items()}
for y in range(Ht):
    for x in range(W):
        im.putpixel((x, y), c["b"] if ((x + y) // 4) % 2 == 0 else c["a"])
rnd = random.Random(3)
for k in range(14):
    sx, sy = 3 + (k * 13) % (W - 6), 3 + (k * 7 + (k // 4) * 5) % (Ht - 6)
    for dx, dy in [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (-2, 0), (0, 2), (0, -2)]:
        im.putpixel((sx + dx, sy + dy), c["s"])
im.save("textures/wallpaper.png")

# ---- the cabinet: interior x -2.2..2.2, z -1.1 (back wall) .. 1.35 (the glass), floor y 0, the
# header's underside y 3.2. The frame round the glass (z 1.35..1.5) hides the world outside.
L = [mat("Wallpaper", "#ffffff"), "material texture Wallpaper base-color textures/wallpaper.png",
     mat("Side", HOT), mat("Floor", PLUM), mat("Frame", HOT), mat("Trim", PINK), mat("Rail", PERI),
     mat("ChuteWall", RED), mat("ChuteRim", YEL), mat("Hole", DARK), mat("BulbOff", PLUM)]
# the back wall: a slab whose front face carries the wallpaper
L += box("Back", -2.2, 2.2, 0, 3.6, -1.2, -1.1, "Wallpaper")
L += ["active Back", "mode edit", 'select face where "normal.y > -0.9"', "delete only-faces", "select all",
      "uv project-from-view front --scale-to-bounds", "mode object"]
L += box("SideL", -2.3, -2.2, 0, 3.6, -1.1, 1.35, "Side")
L += ["active SideL", "mode edit", 'select face where "normal.x < 0.9"', "delete only-faces", "mode object"]
L += box("SideR", 2.2, 2.3, 0, 3.6, -1.1, 1.35, "Side")
L += ["active SideR", "mode edit", 'select face where "normal.x > -0.9"', "delete only-faces", "mode object"]
L += box("Floor", -2.2, 2.2, -0.1, 0, -1.1, 1.35, "Floor")
L += ["active Floor", "mode edit", 'select face where "normal.z < 0.9"', "delete only-faces", "mode object"]
# the frame: two pillars, the header, the lip; a pale trim strip round the opening
L += box("PillarL", -4.2, -2.2, 0, 3.9, 1.35, 1.5, "Frame")
L += box("PillarR", 2.2, 4.2, 0, 3.9, 1.35, 1.5, "Frame")
L += box("Header", -2.2, 2.2, 3.2, 3.9, 1.35, 1.5, "Frame")
L += box("Lip", -2.2, 2.2, -0.2, 0.22, 1.35, 1.5, "Frame")
L += box("TrimL", -2.32, -2.2, 0.22, 3.2, 1.38, 1.53, "Trim")
L += box("TrimR", 2.2, 2.32, 0.22, 3.2, 1.38, 1.53, "Trim")
L += box("TrimT", -2.32, 2.32, 3.2, 3.3, 1.38, 1.53, "Trim")
L += box("TrimB", -2.32, 2.32, 0.12, 0.22, 1.38, 1.53, "Trim")
# the gantry's rails along x, under the header's line
L += box("RailF", -2.2, 2.2, 3.08, 3.18, 1.05, 1.15, "Rail")
L += box("RailB", -2.2, 2.2, 3.08, 3.18, -1.05, -0.95, "Rail")
# the prize chute: front left, x -2.2..-1.3, z 0.3..1.35, walls 0.75 high, a yellow rim, a dark hole
L += box("ChF", -2.2, -1.3, 0, 0.75, 1.25, 1.35, "ChuteWall")
L += box("ChB", -2.2, -1.3, 0, 0.75, 0.3, 0.4, "ChuteWall")
L += box("ChR", -1.4, -1.3, 0, 0.75, 0.3, 1.35, "ChuteWall")
L += box("RimF", -2.2, -1.26, 0.75, 0.84, 1.21, 1.37, "ChuteRim")
L += box("RimB", -2.2, -1.26, 0.75, 0.84, 0.26, 0.42, "ChuteRim")
L += box("RimR", -1.44, -1.26, 0.75, 0.84, 0.26, 1.37, "ChuteRim")
L += box("Hole", -2.2, -1.4, 0.0, 0.08, 0.4, 1.25, "Hole")
# unlit bulbs along the back wall's top edge and down its corners (the lit sets cover them: game bones)
BULBS = [(-2.0 + i * 0.4, 3.32, -1.04) for i in range(11)]
BULBS += [(-2.08, 0.9 + i * 0.4, -1.04) for i in range(6)] + [(2.08, 0.9 + i * 0.4, -1.04) for i in range(6)]
names = []
for i, (bx, by, bz) in enumerate(BULBS):
    names.append(f"Off{i}")
    L.append(f"add mesh ico-sphere --name Off{i} --subdivisions 1 --radius 0.08 --location {H(bx, by, bz)}")
L += ["select " + " ".join(names), f"active {names[0]}", "join", "material assign BulbOff"]
L += ["select all", "shade flat", "export cabinet.glb"]
write("cabinet", L, "The claw machine's cabinet: wallpapered back wall, side walls, floor, the frame round the "
      "glass with a pale trim, the gantry rails, the prize chute (front left) and the unlit bulbs.")

# the lit bulbs: two alternating sets (the game swaps them: chase lights)
for setname, par in (("bulbs_a", 0), ("bulbs_b", 1)):
    L = [mat("Bulb", YEL, True)]
    names = []
    for i, (bx, by, bz) in enumerate(BULBS):
        if i % 2 != par:
            continue
        names.append(f"B{i}")
        L.append(f"add mesh ico-sphere --name B{i} --subdivisions 1 --radius 0.095 --location {H(bx, by, bz + 0.01)}")
    L += ["select " + " ".join(names), f"active {names[0]}", "join", "material assign Bulb", "shade flat", f"export {setname}.glb"]
    write(setname, L, f"Lit chase-light bulbs, set {setname[-1].upper()} (every other bulb), unlit yellow.")

# ---- the ball pit: a mound of small balls in three cool colours over three dark heaps
def pile_h(x, z):
    return 0.12 + 0.36 * math.exp(-((x - 0.25) ** 2 / 2.4 + (z + 0.15) ** 2 / 1.1))

def in_chute(x, z):
    return x < -1.15 and z > 0.2

open("pile.json", "w").write('{"base": 0.12, "amp": 0.36, "cx": 0.25, "sx2": 2.4, "cz": -0.15, "sz2": 1.1, "ball": 0.13}\n')
rnd = random.Random(9)
L = [mat("Heap", PLUM), mat("BallA", BLUE), mat("BallB", PERI), mat("BallC", LILAC)]
for i, (hx, hz, rx, rz, hh) in enumerate([(0.25, -0.1, 2.0, 1.1, 0.42), (-1.2, -0.4, 1.1, 0.75, 0.2), (1.6, 0.2, 1.0, 1.0, 0.25)]):
    L += [f"add mesh ico-sphere --name Heap{i} --subdivisions 2 --radius 1 --location {H(hx, 0, hz)}",
          f"scale {rx} {rz} {hh}", "apply --scale", "material assign Heap"]
groups = {"BallA": [], "BallB": [], "BallC": []}
k = 0
z = -0.98
row = 0
while z < 1.3:
    x = -2.08 + (0.12 if row % 2 else 0)
    while x < 2.1:
        jx, jz = x + rnd.uniform(-0.04, 0.04), z + rnd.uniform(-0.04, 0.04)
        if not in_chute(jx, jz):
            g = rnd.choice(list(groups))
            nm = f"P{k}"
            groups[g].append(nm)
            y = pile_h(jx, jz) - 0.02 + rnd.uniform(-0.03, 0.03)
            L.append(f"add mesh ico-sphere --name {nm} --subdivisions 1 --radius 0.13 --location {H(jx, y, jz)}")
            k += 1
        x += 0.24
    z += 0.21
    row += 1
for g, ns in groups.items():
    L += ["select " + " ".join(ns), f"active {ns[0]}", "join", f"material assign {g}"]
L += ["select all", "shade flat", "export pit.glb"]
write("pit", L, f"The ball pit: {k} balls r 0.13 in blue, periwinkle and lilac on a mound "
      "(height 0.12 + 0.36 exp(-((x-0.25)^2/2.4 + (z+0.15)^2/1.1))), dark heaps under them.")

# ---- the gantry: the bridge (a beam along z, moved in x) and the trolley (moved in x and z)
write("bridge", [mat("Rail", PERI)] + box("Beam", -0.07, 0.07, -0.07, 0.07, -1.0, 1.1, "Rail") + ["shade flat", "export bridge.glb"],
      "The gantry bridge: a chrome beam 2.1 m along z (-1.0..1.1), origin at its middle.")
write("trolley", [mat("Body", RED), mat("Top", YEL)] + box("Body", -0.2, 0.2, 0, 0.22, -0.2, 0.2, "Body")
      + box("Lid", -0.16, 0.16, 0.22, 0.28, -0.16, 0.16, "Top") + ["select all", "shade flat", "export trolley.glb"],
      "The trolley under the bridge: a red box 0.4 m with a yellow lid, origin at its bottom middle.")

# ---- toys, origin at the bottom middle, facing the camera, about 0.55 m tall
def ico(name, r, X, Y, Z, sx=1, sy=1, sz=1, sub=2, m=None):
    L = [f"add mesh ico-sphere --name {name} --subdivisions {sub} --radius {r} --location {H(X, Y, Z)}"]
    if (sx, sy, sz) != (1, 1, 1):
        L += [f"scale {sx} {sz} {sy}", "apply --scale"]
    if m:
        L.append(f"material assign {m}")
    return L

L = [mat("Body", YEL), mat("Beak", PEACH), mat("Eye", DARK)]
L += ico("Body", 0.25, 0, 0.21, 0, 1.0, 0.82, 1.2, m="Body")
L += ico("Head", 0.17, 0, 0.46, 0.13, m="Body")
L += ico("Wing", 0.13, 0, 0.24, -0.04, 2.1, 0.62, 0.95, sub=1, m="Body")
L += [f"add mesh cone --name Beak --vertices 6 --radius1 0.08 --radius2 0.02 --depth 0.16 --location {H(0, 0.43, 0.32)} --rotation 90 0 0",
      "material assign Beak",
      f"add mesh cone --name Tail --vertices 4 --radius1 0.09 --radius2 0 --depth 0.17 --location {H(0, 0.33, -0.3)} --rotation -55 0 0",
      "material assign Body",
      f"add mesh cube --name EyeL --size 0.06 --location {H(-0.085, 0.51, 0.27)}", "material assign Eye",
      f"add mesh cube --name EyeR --size 0.06 --location {H(0.085, 0.51, 0.27)}", "material assign Eye",
      "select all", "shade flat", "export duck.glb"]
write("duck", L, "Rubber duck: yellow body and head, peach beak, dark eyes, 0.62 m tall.")

L = [mat("Fur", PINK), mat("Snout", WHITE), mat("Eye", DARK)]
L += ico("Body", 0.21, 0, 0.21, 0, 1, 1.05, 0.9, m="Fur")
L += ico("Head", 0.17, 0, 0.5, 0.02, m="Fur")
L += ico("EarL", 0.075, -0.13, 0.64, 0, sub=1, m="Fur") + ico("EarR", 0.075, 0.13, 0.64, 0, sub=1, m="Fur")
L += ico("ArmL", 0.085, -0.2, 0.27, 0.08, sub=1, m="Fur") + ico("ArmR", 0.085, 0.2, 0.27, 0.08, sub=1, m="Fur")
L += ico("LegL", 0.09, -0.12, 0.07, 0.12, sub=1, m="Fur") + ico("LegR", 0.09, 0.12, 0.07, 0.12, sub=1, m="Fur")
L += ico("Snout", 0.08, 0, 0.45, 0.16, sub=1, m="Snout")
L += [f"add mesh cube --name EyeL --size 0.06 --location {H(-0.07, 0.55, 0.16)}", "material assign Eye",
      f"add mesh cube --name EyeR --size 0.06 --location {H(0.07, 0.55, 0.16)}", "material assign Eye",
      "select all", "shade flat", "export bear.glb"]
write("bear", L, "Teddy bear: pink fur, white snout, dark eyes, 0.72 m tall.")

L = [mat("Fur", WHITE), mat("Nose", HOT), mat("Eye", DARK)]
L += ico("Body", 0.2, 0, 0.2, 0, 1, 1.05, 0.95, m="Fur")
L += ico("Head", 0.16, 0, 0.46, 0.03, m="Fur")
L += ico("Tail", 0.08, 0, 0.16, -0.2, sub=1, m="Fur")
for nm, sx, rot in (("EarL", -0.07, -10), ("EarR", 0.07, 10)):
    L += [f"add mesh cube --name {nm} --size 1 --location {H(sx * 1.25, 0.72, 0.02)}", "scale 0.09 0.06 0.3", "apply --scale",
          f"set rotation 0 {rot} 0", "apply --rotation", "material assign Fur"]
L += [f"add mesh cube --name Nose --size 0.06 --location {H(0, 0.44, 0.19)}", "material assign Nose",
      f"add mesh cube --name EyeL --size 0.06 --location {H(-0.065, 0.5, 0.15)}", "material assign Eye",
      f"add mesh cube --name EyeR --size 0.06 --location {H(0.065, 0.5, 0.15)}", "material assign Eye",
      "select all", "shade flat", "export bunny.glb"]
write("bunny", L, "Bunny: white fur, long ears, a pink nose, dark eyes, 0.86 m tall.")

L = [mat("White", WHITE), mat("Red", RED), mat("Yellow", YEL), mat("Mint", MINT)]
L += ico("Ball", 0.27, 0, 0.27, 0, m="White")
L += ["active Ball", "mode edit", "select mode face", "select none", 'select face where "pos.x > 0.1 && pos.z < 0.2"', "material assign Red",
      "select none", 'select face where "pos.x < -0.1 && pos.z < 0.2"', "material assign Yellow",
      "select none", 'select face where "abs(pos.x) <= 0.1 && pos.y < -0.12 && pos.z < 0.2"', "material assign Mint",
      "mode object", "shade flat", "export ball.glb"]
write("ball", L, "Beach ball: r 0.27, red, white, yellow and mint segments.")

L = [mat("Gem", MINT), mat("Facet", "#acfcad")]
L += [f"add mesh cone --name Low --vertices 6 --radius1 0.02 --radius2 0.25 --depth 0.26 --location {H(0, 0.13, 0)}",
      "material assign Gem",
      f"add mesh cone --name High --vertices 6 --radius1 0.25 --radius2 0.13 --depth 0.17 --location {H(0, 0.345, 0)}",
      "material assign Gem",
      "active High", "mode edit", 'select face where "normal.z > 0.9"', "material assign Facet", "mode object",
      "active Low", "mode edit", 'select face where "normal.z > 0.9"', "delete only-faces", "mode object",
      "select all", "shade flat", "export gem.glb"]
write("gem", L, "The jackpot gem: a mint six-sided crystal 0.5 m across, 0.43 m tall, a pale table on top.")

for nm, col in (("confetti_y", YEL), ("confetti_m", MINT)):
    write(nm, [mat("Bit", col, True), "add mesh cube --name Bit --size 0.1", "scale 1 0.5 1", "apply --scale", "material assign Bit",
               f"export {nm}.glb"], f"Confetti: a 0.1 m unlit chip ({col}).")
